// 模拟视频转录结果 (支持中英对照)
function getMockTranscription(url) {
  const isEnglish = url.toLowerCase().includes('youtube') || url.toLowerCase().includes('english') || url.toLowerCase().includes('foreign');

  if (isEnglish) {
    return {
      video_url: url,
      duration: "08:45",
      language: "en-US",
      title: "Model Context Protocol Explained (MCP Guide)",
      segments: [
        { 
          start: "00:00", 
          end: "01:15", 
          text: "ENG: Today we are talking about Model Context Protocol, the open standard to connect LLMs to data sources.\nCHS: 今天我们来聊聊模型上下文协议 (MCP)，这是一套连接大模型与数据源的开放标准。" 
        },
        { 
          start: "01:15", 
          end: "03:40", 
          text: "ENG: With MCP, your agent can inspect database tables and run APIs securely in the background.\nCHS: 借助 MCP，您的智能体能够安全地在后台审查数据库表格并运行 API。" 
        },
        { 
          start: "03:40", 
          end: "06:10", 
          text: "ENG: This solves the integration problem, so you don't have to build custom integrations for every platform.\nCHS: 这解决了系统集成问题，因此您无需为每个平台都构建定制化的集成方案。" 
        },
        { 
          start: "06:10", 
          end: "08:45", 
          text: "ENG: Let's see how we write a simple Node.js MCP server from scratch in under 5 minutes.\nCHS: 让我们来看看如何在 5 分钟内从头编写一个简单的 Node.js MCP 服务器。" 
        }
      ]
    };
  }

  // 默认中文视频 Mock
  return {
    video_url: url,
    duration: "15:24",
    language: "zh-CN",
    title: "昆仑增长冷启动搞流量的底层闭环方法论",
    segments: [
      { start: "00:00", end: "01:30", text: "大家好，我是帅总。今天我们来拆解一下如何从0到1快速起号，搞定小红书和公众号的私域闭环。" },
      { start: "01:30", end: "05:10", text: "首先，核心的痛点在于选题。不要制造一些AI味很浓的废话，一定要找用户的痛点卡点进行冲突对比。" },
      { start: "05:10", end: "10:15", text: "其次是转化。AI销冠的核心不是卖货，而是通过BANT模型判定用户的预算和需求，精准切入核心痛点。" },
      { start: "10:15", end: "15:24", text: "最后，交付是口碑的保证。我们要建立多维表格的交付看板，让每一个会员提出的答疑工单在24小时内闭环。" }
    ]
  };
}

